/* From Uiverse.io by elijahgummer  - Tags: simple, animation, blue, checkbox, modern, transition, click effect, click animation */
.__UIV_SCOPE__ .checkbox {
  position: relative;
}

.__UIV_SCOPE__ .checkbox input[type="checkbox"] {
  display: none;
  visibility: hidden;
}

.__UIV_SCOPE__ .checkbox .cbx {
  -webkit-perspective: 20;
  perspective: 20;
  display: inline-block;
  border: 2px solid #e8e8eb;
  background: #e8e8eb;
  border-radius: 4px;
  transform: translate3d(0, 0, 0);
  cursor: pointer;
  transition: all 0.3s ease;
}

.__UIV_SCOPE__ .checkbox .cbx:hover {
  border-color: #0b76ef;
}

.__UIV_SCOPE__ .checkbox .flip {
  display: block;
  transition: all 0.4s ease;
  transform-style: preserve-3d;
  position: relative;
  width: 20px;
  height: 20px;
}

.__UIV_SCOPE__ .checkbox input[type="checkbox"]:checked + .cbx {
  border-color: #0b76ef;
}

.__UIV_SCOPE__ .checkbox input[type="checkbox"]:checked + .cbx .flip {
  transform: rotateY(180deg);
}

.__UIV_SCOPE__ .checkbox .front,
.__UIV_SCOPE__ .checkbox .back {
  backface-visibility: hidden;
  position: absolute;
  top: 0;
  left: 0;
  width: 20px;
  height: 20px;
  border-radius: 2px;
}

.__UIV_SCOPE__ .checkbox .front {
  background: #fff;
  z-index: 1;
}

.__UIV_SCOPE__ .checkbox .back {
  transform: rotateY(180deg);
  background: #0b76ef;
  text-align: center;
  color: #fff;
  line-height: 20px;
  box-shadow: 0 0 0 1px #0b76ef;
}

.__UIV_SCOPE__ .checkbox .back svg {
  margin-top: 3px;
  fill: none;
}

.__UIV_SCOPE__ .checkbox .back svg path {
  stroke: #fff;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}
